// No Flutter service worker (deprecated); sw.js is generated by
// tool/build_web.sh and makes the game work offline after the first visit.
_flutter.loader.load({
  onEntrypointLoaded: async (engineInitializer) => {
    const appRunner = await engineInitializer.initializeEngine();
    const loading = document.getElementById('loading');
    await appRunner.runApp();
    if (loading) {
      loading.style.opacity = '0';
      setTimeout(() => loading.remove(), 400);
    }
  },
});

if ('serviceWorker' in navigator) {
  window.addEventListener('load', async () => {
    try {
      const reg = await navigator.serviceWorker.register('sw.js');
      // Hand the files this page already loaded (e.g. the CanvasKit variant
      // this browser picked) to the worker so they are cached for offline.
      const urls = performance.getEntriesByType('resource')
        .map((e) => e.name)
        .filter((u) => u.startsWith(location.origin));
      const send = (w) => w && w.postMessage({ type: 'cache', urls });
      await navigator.serviceWorker.ready;
      send(reg.active);
    } catch (e) {
      console.warn('service worker', e);
    }
  });
}
